from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.ue import TM500


class _TM500Wrapper(ListAbstractionsWrapper):
    """
    All redirections for tm500 are contained inside this wrapper's properties
    """
    def __init__(self, tl_config):
        super(_TM500Wrapper, self).__init__(tl_config)
        self.tm500 = self.get_instance(TM500, self.tl_config.ues)

    @property
    def addr(self):
        return self.tm500.tma_host.addr

    @property
    def username(self):
        return self.tm500.tma_host.username

    @property
    def password(self):
        return self.tm500.tma_host.password
